+   for (i=0;i<6;i++) layout.mapping[i] = (unsigned char)i;
+   check_surround_layout(255, &layout); cfgs++;
+
+   /* Family 2: pure Ambisonic layouts.  The ACN channels are coded as
+      uncoupled mono streams in ACN order; valid counts are perfect squares
+      (order+1)^2 up to 15^2=225. */
