opus_int32 test_msenc_api(void)
{
   opus_int32 cfgs = 0;
   SurroundLayout layout;
   int i;

   fprintf(stdout,"\n  Multistream surround/ambisonics encoder API tests\n");
   fprintf(stdout,"  ---------------------------------------------------\n");

   /* Family 0: mono and stereo only. */
   memset(&layout, 0, sizeof(layout));
   layout.channels = 1; layout.streams = 1; layout.coupled_streams = 0;
   layout.mapping[0] = 0;
   check_surround_layout(0, &layout); cfgs++;
   memset(&layout, 0, sizeof(layout));
   layout.channels = 2; layout.streams = 1; layout.coupled_streams = 1;
   layout.mapping[0] = 0; layout.mapping[1] = 1;
