         {0,4,1,2,3,5,6},
         {0,6,1,2,3,4,5,7}
      };
      streams = coupled_streams = -1;
      err = opus_multistream_surround_encoder_init(NULL, 48000, i, 1,
         &streams, &coupled_streams, layout.mapping, OPUS_APPLICATION_AUDIO);
      if (err <= 0) test_failed();
      layout.channels = i;
      layout.streams = streams;
      layout.coupled_streams = coupled_streams;
      for (err=0;err<i;err++)
         if (layout.mapping[err] != vorbis_mapping[i-1][err]) test_failed();
      check_surround_layout(1, &layout); cfgs++;
